  var translation_fallback = "NO_TRANSLATION_FOUND";
  function tl2(key, replacements = {}, string = true) {
    if (typeof key === "string") {
      if (lang == "fae") return "hazelfae";
      return key;
    }
    if (!key) {
      log("your key is undefined", "trans");
      if (lang == "fae") return "hazelfae";
      return translation_fallback;
    }
    let translation = key[lang] || key.en;
    if (page.state.april && translation.includes("Last.fm Pro")) {
      translation = translation.replaceAll("Last.fm Pro", "Verified");
    }
    if (Object.keys(replacements).length == 0) {
      if (lang == "fae") {
        return "hazelfae";
      }
      return translation;
    }
    if (string) {
      for (let [placeholder, value] of Object.entries(replacements)) {
        const regex = new RegExp(`{${placeholder}}`, "g");
        if (lang == "fae") value = "hazelfae";
        translation = translation.replace(regex, value);
      }
      return translation;
    }
    const parts = translation.split(/({[^}]+})/g);
    return parts.map((part) => {
      const match3 = part.match(/^\{(\w+)\}$/);
      if (lang == "fae") return "hazelfae";
      if (match3) {
        const key2 = match3[1];
        return replacements[key2] ?? part;
      }
      return part;
    });
  }
  function collect_keys(object, prefix, out = []) {
    for (const k4 in object) {
      const val = object[k4];
      const key = prefix ? `${prefix}.${k4}` : k4;
      if (typeof val == "object" && !Object.keys(lang_info).some((lang2) => lang2 in val)) {
        collect_keys(val, key, out);
      } else {
        out.push(key);
      }
    }
    return out;
  }
  function get_value_by_path(object, path) {
    return path.split(".").reduce((acc, part) => acc?.[part], object);
  }
  function translation_stats() {
    const keys4 = collect_keys(trans);
    for (const lang2 of Object.keys(lang_info)) {
      let translated = 0;
      const missing = [];
      for (const key of keys4) {
        const value = get_value_by_path(trans, key);
        if (value && value[lang2]) {
          translated++;
        } else {
          missing.push(key);
        }
      }
      lang_info[lang2].total = keys4.length;
      lang_info[lang2].translated = translated;
      lang_info[lang2].missing = missing.length;
      lang_info[lang2].missing_keys = missing;
      lang_info[lang2].percent = Math.round(translated / keys4.length * 100);
    }
    log("translation stats", "trans", "info", {
      lang_info
    });
  }
  function get_lang() {
    const path = window.location.pathname;
    const segments = path.split("/");
    const lang2 = segments[1];
    if (/^[a-z]{2}$/.test(lang2)) {
      return `/${lang2}/`;
    }
    return "/";
  }
  function lookup_lang() {
    setRoot(get_lang());
    const params = new URLSearchParams(document.location.search);
    const hazelfae = params.get("hazelfae");
    if (!page.state.hazelfae) {
      page.state.hazelfae = hazelfae != void 0;
    }
    if (page.state.hazelfae) {
      lang = "fae";
    } else {
      lang = document.documentElement.getAttribute("lang");
    }
    lang_browser = navigator.language.replaceAll('"', "");
    if (lang.startsWith("en") && lang_browser.startsWith("en")) {
      Settings.defaultLocale = lang_browser;
    } else {
      Settings.defaultLocale = lang;
    }
    log(`using locale ${Settings.defaultLocale}`, "lang", "info", {
      lang,
      lang_browser
    });
  }
  function get_trans_key(key) {
    return key.split(".").reduce((trans2, key2) => trans2[key2], trans);
  }

