  function manage_oracle_data() {
    const oracle = JSON.parse(localStorage.getItem("bleh_oracle_cache")) || {};
    console.info("oracle data", oracle);
    dialog({
      id: "oracle",
      title: tl2(trans.manage_data),
      body: html.node`
            <div class="data-table">
                ${Object.entries(oracle).map(([artist, data2]) => load_artist(artist, data2))}
            </div>
        `,
      allow_scroll: true
    });
    function load_artist(artist, data2) {
      const entry = html.node`
            <div class="data-table-entry">
                <div class="entry-header">
                    <strong class="entry-header-text">${artist}</strong>
                    <div class="entry-actions">
                        <button class="btn icon danger-subtle chibi" data-type="delete" onclick=${() => delete_artist()}>${tl2(trans.delete)}</button>
                    </div>
                </div>
                <div class="entry-data">
                    ${Object.entries(data2).map(([item, data3]) => load_item(item, data3, artist))}
                </div>
            </div>
        `;
      function delete_artist() {
        delete oracle[artist];
        log("deleted artist", "oracle", "info", {
          artist,
          oracle
        });
        save_cache();
        entry.remove();
      }
      return entry;
    }
    function load_item(item, data2, artist) {
      const entry = html.node`
            <div class="data-table-entry">
                <div class="entry-header">
                    <strong class="entry-header-text">${item}</strong>
                    <div class="entry-actions">
                        <button class="btn icon danger-subtle chibi" data-type="delete" onclick=${() => delete_item()}>${tl2(trans.delete)}</button>
                    </div>
                </div>
                <div class="entry-data">
                    ${data2.album && Object.keys(data2.album).length > 0 ? load_item_data("album", data2.album, item, artist) : ""}
                    ${data2.track && Object.keys(data2.track).length > 0 ? load_item_data("track", data2.track, item, artist) : ""}
                </div>
            </div>
        `;
      function delete_item() {
        delete oracle[artist][item];
        log("deleted item", "oracle", "info", {
          item,
          artist,
          oracle
        });
        save_cache();
        entry.remove();
      }
      return entry;
    }
    function load_item_data(type, data2, item, artist) {
      const entry = html.node`
            <div class="data-table-entry">
                <div class="entry-header">
                    <strong class="entry-type">
                        ${icon({
        name: icons[type]
      })}
                        ${type}
                    </strong>
                    <div class="entry-subdata">
                        ${data2.date ? html.node`
                            <div class="entry-data-row">
                                <strong class="entry-data-head">fetched:</strong>
                                <p class="entry-data-text">${DateTime.fromMillis(data2.date).toRelative()}</p>
                            </div>
                        ` : ""}
                        ${data2.expire ? html.node`
                            <div class="entry-data-row">
                                <strong class="entry-data-head">expires:</strong>
                                <p class="entry-data-text">${DateTime.fromMillis(data2.expire).toRelative()}</p>
                            </div>
                        ` : ""}
                    </div>
                    <div class="entry-actions">
                        <button class="btn icon danger-subtle chibi" data-type="delete" onclick=${() => delete_item()}>${tl2(trans.delete)}</button>
                    </div>
                </div>
                <div class="entry-subdata">
                    ${data2.id ? html.node`
                        <div class="entry-data-row">
                            <p>id: ${data2.id}</p>
                        </div>
                    ` : ""}
                    ${data2.artwork ? html.node`
                        <div class="entry-data-row">
                            <p>artwork</p>
                        </div>
                    ` : ""}
                </div>
            </div>
        `;
      function delete_item() {
        delete oracle[artist][item][type];
        log("deleted item sub", "oracle", "info", {
          type,
          item,
          artist,
          oracle
        });
        save_cache();
        entry.remove();
      }
      return entry;
    }
    function save_cache() {
      log("saved to cache", "oracle", "info", {
        oracle
      });
      set_storage("bleh_oracle_cache", JSON.stringify(oracle));
    }
  }
  function report_incorrect() {
    if (settings.tracklist_source != "oracle" && page.type == "album") {
      return;
    }
    let title = `${correct_artist(page.sister)} - ${correct_item_by_artist(page.name, page.sister)}`;
    let link = window.location.href;
    let sources;
    let template;
    if (page.type == "track") {
      template = "1-incorrect-albums-assigned-to-track.yml";
    } else {
      template = "2-incorrect-album-listing.yml";
    }
    dialog({
      id: "oracle_correction",
      title: tl2(trans.suggest_correction),
      body: html.node`
            <div class="new-scrobble-form">
                <p class="generic-label">${tl2(trans.what_did_you_expect)}</p>
                ${sources = input({
        type: "textarea"
      })}
                <p class="form-tip">${tl2(trans[`oracle_sources_tip_${page.type}`])}</p>
            </div>
            <div class="modal-footer">
                <button class="see-more cancel left-icon" onclick=${() => dialog_rm({
        id: "oracle_correction"
      })}>
                    ${tl2(trans.cancel)}
                </button>
                <div class="fill" />
                <button class="btn primary continue" onclick=${() => {
        open(`https://github.com/katelyynn/oracle/issues/new?template=${template}&title=${sanitise(title, " ")}&link=${encodeURIComponent(link)}&sources=${sanitise(sources.value, " ")}`);
      }}>
                    ${tl2(trans.suggest)}
                </button>
            </div>
        `
    });
  }

