    async function fetch_data_set(user2, media, change_history = true) {
      if (change_history) {
        const data_source_history = import_json53.default.parse(localStorage.getItem(keys3.plot_data_history) || "[]");
        if (!data_source_history.some((item) => import_json53.default.stringify(item) == import_json53.default.stringify(media))) {
          data_source_history.push(media);
        } else {
          data_source_history.splice(data_source_history.indexOf(media), 1);
          data_source_history.push(media);
        }
        if (data_source_history.length > 30) {
          data_source_history.shift();
        }
        localStorage.setItem(keys3.plot_data_history, import_json53.default.stringify(data_source_history));
      }
      const data_point = import_json53.default.parse(media);
      let media_url;
      let type;
      if (data_point.album && data_point.artist) {
        media_url = `${sanitise(data_point.artist)}/${sanitise(data_point.album)}`;
      } else if (data_point.track && data_point.artist) {
        media_url = `${sanitise(data_point.artist)}/_/${sanitise(data_point.track)}`;
      } else {
        media_url = sanitise(data_point.artist);
      }
      const url = `${root}user/${user2}/library/music/${redirect()}${media_url}?${timeframe.value}`;
      console.info("timeframe url", url);
      const res = await fetch(url);
      if (!res.ok) {
        log("failed to fetch", "plot", "error", {
          res
        });
        return;
      }
      const dom = await res.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(dom, "text/html");
      const table = doc.querySelector(".scrobble-table");
      if (!table) {
        log("failed to find table", "plot", "error", {
          table
        });
        return;
      }
      chart_bucket = table.getAttribute("data-bucket-size");
      const entries2 = table.querySelectorAll("tbody tr");
      console.info("table", table, entries2);
      const point = {
        user: user2,
        media: data_point,
        data: [],
        borderWidth: 2,
        fill: true,
        pointRadius: 0,
        pointHitRadius: 20,
        tension: 0.1
      };
      let seen_over_0 = false;
      const length = Array.from(entries2).length;
      entries2.forEach((entry, index3) => {
        const period = entry.querySelector(".js-period > a")?.getAttribute("href");
        const params = new URLSearchParams(period);
        const from3 = params.get("from");
        const scrobbles = Number(entry.querySelector(".js-scrobbles").textContent.trim());
        if (scrobbles > 0 || index3 + 1 >= length / 2) seen_over_0 = true;
        point.data.push({
          x: from3,
          y: scrobbles,
          hide: !seen_over_0 && scrobbles == 0
        });
      });
      data_points.push(point);
      update_plot_options();
      plot_footer();
      update_chart(change_history);
    }
