  function load_badges(user, solo = false) {
    if (!sponsor_list.version) return;
    let badges = [];
    const trans_contributions = get_trans_contributions(user);
    log(`found ${trans_contributions.length} contribution(s) for ${user}`, "sponsor", "info", {
      trans_contributions
    });
    if (trans_contributions.length > 0) {
      trans_contributions.forEach((contribution) => {
        badges.push({
          type: "translation",
          translation_code: contribution.code,
          reason: contribution.name
        });
      });
    }
    let entry = sponsor_list.users[user];
    if (entry) {
      entry = {
        sponsor: true,
        contributor: false,
        ...entry
      };
      if (entry.contributor) {
        badges.push({
          type: "contributor"
        });
      }
      if (entry.sponsor) {
        badges.push({
          type: "sponsor"
        });
      }
      if (entry.badges) {
        log("multiple badges found", "sponsor", "info", sponsor_list.users[user].badges);
        badges = [
          ...badges,
          ...sponsor_list.users[user].badges
        ];
      }
    }
    badges.forEach((badge) => {
      if (entry && entry.sponsor && !badge.type) badge.type = "sponsor";
      badge = process_badge(badge, user);
    });
    log(`final badge list for @${user}`, "sponsor", "info", {
      badges
    });
    if (solo) return badges[badges.length - 1];
    return badges;
  }
