  function settings_search(tabs) {
    return html.node`
        <section class="settings-search">
            ${input({
      placeholder: tl2(trans.search_for_settings),
      func: (query) => {
        const results = make_search(tabs, query);
        change_settings_page("search");
        search_results(tabs, query, results);
      },
      icon: icons.search
    })}
        </section>
    `;
  }
  function make_search(tabs, query) {
    query = query.toLowerCase().trim();
    const results = [];
    Object.entries(tabs).forEach(([key, tab]) => {
      if (!tab.settings) return;
      tab.settings.forEach((setting2) => {
        const formal = settings_store[setting2];
        if (!formal) return;
        let match3 = false;
        const name = tl2(formal.title).toLowerCase() || "";
        const body = tl2(formal.body).toLowerCase() || "";
        const tags = formal.tags;
        if (tags) {
          tags.forEach((tag) => {
            if (typeof tag == "string") {
              if (tag.toLowerCase().includes(query)) match3 = true;
            } else if (typeof tag == "object") {
              if (tl2(tag).toLowerCase().includes(query)) match3 = true;
            }
          });
        }
        if (name.includes(query) || body.includes(query)) {
          match3 = true;
        }
        if (match3) {
          results.push({
            id: setting2,
            tab: key
          });
        }
      });
    });
    return results;
  }
  function search_results(tabs, query, results) {
    render(page.structure.main, html`
			<section class="search-result-container">
				<p class="setting-search-results-count">${tl2(trans.found_value_results, {
      c: results.length
    })}</p>
				<div class="setting-search-results">
			        ${results.map((result) => {
      const tab = tabs[result.tab];
      const formal = settings_store[result.id];
      return html.node`
                        <button class="btn setting-search-result" onclick=${() => finalise_result(result)}>
                            <div class="bleh-icon" style="--icon: var(--mask)" data-bleh-page=${result.tab} data-type=${tab.icon} />
                            <div class="setting-search-result-info">
                                <strong class="setting-search-result-header">${tl2(formal.title)}</strong>
                                ${formal.body ? html.node`
                                    <p class="setting-search-result-body">${tl2(formal.body)}</p>
                                ` : ""}
                            </div>
                            <p class="setting-search-result-context">${tab.name}</p>
                        </button>
                    `;
    })}
			    </div>
			</section>
		`);
  }
  function finalise_result(result) {
    change_settings_page(result.tab);
    scroll_to_setting(result.id);
  }

