  function campfire_friend(friend, own = false) {
    let track_info;
    let user_avatar;
    let user_name;
    let track_time;
    const elem = html.node`
        <div class="user friend hidden-user" data-live="false" data-own=${own}>
          <div class="user-avatar avatar" ref=${(el) => user_avatar = el}>
              <div class="bleh-icon loading-spinner" />
          </div>
            <div class="user-info">
                <div class="user-name">
                    <a class="user-name-inner" href="${root}user/${friend}" ref=${(el) => user_name = el}>@${friend}</a>
                    <span class="track-time icon-mask" ref=${(el) => track_time = el} />
                </div>
                <div class="user-about track" ref=${(el) => track_info = el}>
                  <div class="status">
                      <div class="status-image smaller" />
                  </div>
                </div>
            </div>
        </div>
    `;
    load_profile_cache_externally(friend).then((cache2) => {
      render(user_avatar, html`
				<img src=${own ? auth.avatar : cache2.avatar} alt=${friend}>
			`);
      if (cache2.username) {
        user_name.textContent = cache2.username;
      }
      load_recent_tracks(friend).then((tracks) => {
        const item = tracks[0];
        if (item) {
          let sister = item.sister;
          let name = item.name;
          if (useSettings.get("format_guest_features")) {
            const formatted = name_includes(name, sister);
            name = html.node`${smart_title(formatted.song_title, formatted.song_tags)}`;
            sister = html.node`${smart_artists(formatted.song_artist, formatted.song_guests)}`;
          } else if (useSettings.get("corrections")) {
            sister = romanise(correct_artist(item.sister));
            name = romanise(correct_item_by_artist(item.name, item.sister));
          }
          const valid = is_sponsor(friend);
          if (cache2.username && valid) {
            render(user_name, html`
							<strong class="username-combo">
								<span class="username-custom">${cache2.username}</span>
								<span class="username-original">
							        <span class="at">@</span>${friend}
							    </span>
							</strong>
						`);
          } else {
            render(user_name, html`
							<strong><span class="at">@</span>${friend}</strong>
						`);
          }
          if (!item.live) {
            track_time.textContent = DateTime.fromSeconds(item.time).toRelative();
          } else {
            elem.classList.remove("hidden-user");
            track_time.textContent = tl2(trans.scrobbling_now);
            track_time.setAttribute("data-live", "true");
            elem.setAttribute("data-live", "true");
          }
          render(track_info, html`
						<div class="status">
							<div class="status-image smaller" data-live=${item.live}>
								<img src=${item.avatar} alt=${name}>
							</div>
							<div class="status-info">
								<strong
									class="status-text status-title smaller"><a class="smart-title" href="${root}music/${redirect()}${sanitise(item.sister)}/_/${sanitise(item.name)}">${name}</a></strong>
								<p
									class="status-text status-artist smaller"><span class="artist">${sister}</span></p>
							</div>
						</div>
					`);
        }
      });
    });
    return elem;
  }
