  // src/components/dialog/notices.ts
  function notices() {
    const res = localStorage.getItem("bleh_notices");
    const expire = Number(localStorage.getItem("bleh_notices_expire"));
    const now2 = Date.now();
    if (!res || now2 >= expire) {
      fetch_notices();
      return;
    }
    let parse8;
    try {
      parse8 = JSON.parse(res);
    } catch (e5) {
      fetch_notices();
      return;
    }
    load_notices(parse8);
  }
  function fetch_notices() {
    fetch(`https://katelyynn.github.io/bleh/dynamic/notices.json?${Math.random()}`).then((res) => {
      if (!res.ok) {
        throw new Error();
      }
      return res.json();
    }).then((res) => {
      set_storage("bleh_notices", JSON.stringify(res));
      set_storage("bleh_notices_expire", `${Date.now() + 60 * 60 * 1e3}`);
      load_notices(res);
    }).catch((e5) => {
      set_storage("bleh_notices_expire", `${Date.now() + 30 * 60 * 1e3}`);
    });
  }
  function load_notices(res) {
    const seen = JSON.parse(localStorage.getItem(keys3.notices_seen)) || [];
    document.body.appendChild(html.node`
      <div class="bleh-notices">
          ${res.map((notice) => {
      const date = DateTime.fromISO(notice.date);
      const id = `notice-${notice.type}-${notice.date}`;
      if (seen.includes(id)) return html.node``;
      const elem = html.node`
                  <div class="bleh-notice colourful">
                      <div class="notice-header" data-type=${notice.type}>
                          <span>${tl2(trans.notice)}</span>
                          <span>${date.toRelative()}</span>
                      </div>
                      <div class="notice-content">
                          ${markdown(notice.message)}
                      </div>
                      <div class="notice-close" onclick=${() => {
        seen.push(id);
        set_storage(keys3.notices_seen, JSON.stringify(seen));
        elem.remove();
      }}>
                        ${tl2(trans.close)}
                      </div>
                  </div>
              `;
      return elem;
    })}
      </div>
  `);
  }

  // src/components/music/tags.js
  function tag_page() {
    if (!page.structure.main) return;
    const tags = page.structure.main.querySelectorAll(
      ".big-tags-item:not([data-tagged])"
    );
    tags.forEach((tag) => {
      tag.setAttribute("data-tagged", "true");
      const ctx = tag.querySelector(".big-tags-item-context");
      if (ctx) {
        const links = ctx.querySelectorAll("a");
        links.forEach((link) => {
          link.textContent = romanise(correct_artist(link.textContent));
        });
      }
    });
  }

  // src/components/page/see_more.ts
  function see_more() {
    if (!page.structure.container) return;
    const links = page.structure.container.querySelectorAll(":is(.more-link, .more-link-with-action, .more-link-fullwidth-right, .more-link-fullwidth-right-flush-top, .more-link-fullwidth, .show-more, .music-more-link, .pagination-next, .pagination-previous) > a:not([data-see-more])");
    links.forEach((link) => {
      link.setAttribute("data-see-more", "true");
      const parent = link.parentElement;
      const classes = String(parent.classList);
      link.classList.add("see-more");
      if (classes == "pagination-previous") {
        link.classList.add("pagination-previous-link");
      }
    });
    const parents = page.structure.container.querySelectorAll(".more-link-with-action");
    parents.forEach((parent) => {
      if (parent.nextElementSibling && parent.nextElementSibling.classList.contains("more-link-with-action")) {
        parent.remove();
        return;
      }
      parent.classList = "see-more-row";
    });
    const pagination = page.structure.container.querySelectorAll(".pagination-page:not([data-pagination])");
    pagination.forEach((page2) => {
      page2.setAttribute("data-pagination", "true");
      const current = page2.hasAttribute("aria-current");
      const link = page2.querySelector("a, span");
      link.classList.add("btn", "pagination-page-link");
      if (current) link.setAttribute("aria-checked", "true");
    });
  }

  // src/components/profile/auth.ts
  function register_auth() {
    const handler = document.body.querySelector(".site-auth > .auth-link");
    if (handler) {
      log("found handler", "auth", "info", {
        handler
      });
      const image2 = handler.querySelector(":scope > .auth-avatar-desktop");
      if (!image2) {
        log("no image found", "auth", "error", {
          handler
        });
        return;
      }
      const previous_avatar = auth.avatar;
      log("found image", "auth", "info", {
        image: image2
      });
      auth.name = image2.alt;
      auth.avatar = image2.src;
      log(`registered avatar as ${auth.avatar}, name as ${auth.name}`, "auth", "info", {
        previous_avatar,
        handler
      });
      if (auth.avatar != previous_avatar) {
        image2.setAttribute("crossorigin", "anonymous");
        image2.onload = async () => {
          const { hue: hue4, sat, lit } = await header_colour(image2);
          auth.sets.hue = hue4;
          auth.sets.sat = sat;
          auth.sets.lit = lit;
        };
      }
      return;
    }
    log("no handler found", "auth", "error");
  }

  // src/pages/now/now.ts
  function bleh_now() {
    page.structure.container = document.body.querySelector(".page-content");
    try {
      page.structure.row = page.structure.container.querySelector(".row");
      page.structure.main = page.structure.row.querySelector(".col-main");
      page.structure.side = page.structure.row.querySelector(".col-sidebar");
    } catch (e5) {
      log("unable to find elements", "page structure");
    }
    const content_top = document.body.querySelector(".content-top");
    checkup_page_structure(false, content_top);
    page.type = "bleh_now";
    page.subpage = "";
    log("status is", "page", "info", page);
    update_page();
    page.structure.row.removeChild(page.structure.row.firstElementChild);
    page.structure.row.removeChild(page.structure.row.firstElementChild);
    page.structure.container.classList.add("has-cards-view");
    page.structure.content.classList.add("cards-view");
    let now_header;
    let now_content;
    page.structure.main.classList.add("now-container");
    render(page.structure.main, html`
			<header class="now-header" ref=${(el) => now_header = el} />
			<section class="now-content sour" ref=${(el) => now_content = el} />
		`);
    let now2 = {
      name: null,
      artist: null,
      cover: null
    };
    get_recents(auth.name);
    const timer = setInterval(() => {
      if (!is_url(urls.now)) {
        clearInterval(timer);
        return;
      }
      get_recents(auth.name);
    }, 1e4);
    function get_recents(user) {
      fetch(`${root}user/${user}/partial/recenttracks?ajax=1`).then((res) => res.text()).then((dom) => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(dom, "text/html");
        const list = doc.querySelector(".chartlist");
        if (!list) return;
        const items = list.querySelectorAll(".chartlist-row:not(.chartlist-row--interlist-ad)");
        if (!items) return;
        const most_recent = items[0];
        const name = most_recent.querySelector(".chartlist-name").textContent.trim();
        const artist = most_recent.querySelector(".chartlist-artist").textContent.trim();
        const cover = most_recent.querySelector(".cover-art > img")?.src;
        const previous_now = now2;
        now2 = {
          name,
          artist,
          cover
        };
        if (previous_now.name == name && previous_now.artist == artist) return;
        new_poll();
      });
    }
    function new_poll() {
      console.info("new poll", now2);
      register_background(avatar(now2.cover, "avatar300s"));
      const name = romanise(correct_item_by_artist(now2.name, now2.artist));
      const artist = romanise(correct_artist(now2.artist));
      const song_link = html.node`
            <a href="${root}music/${now2.artist}/_/${now2.name}" target="_blank" />
        `;
      let artist_link = html.node`
            <a href="${root}user/${now2.artist}" target="_blank">${artist}</a>
        `;
      if (useSettings.get("format_guest_features")) {
        const formatted = name_includes(now2.name, now2.artist);
        song_link.classList.add("smart-title");
        render(song_link, smart_title(formatted.song_title, formatted.song_tags));
        artist_link = html.node`${smart_artists(formatted.song_artist, formatted.song_guests)}`;
      } else {
        song_link.textContent = name;
      }
      let now_image;
      render(now_header, html``);
      render(now_header, html`
				<div class="now-header-image-container">
					<div class="now-header-image cover-art colourful" ref=${(el) => now_image = el}>
						<img src=${avatar(now2.cover, "500x500")} alt=${name}>
					</div>
					<div class="now-header-image now-header-image-reflect">
						<img src=${avatar(now2.cover, "500x500")} alt=${name}>
					</div>
				</div>
				<div class="now-header-info">
					<h1 class="now-header-head">
				        ${song_link}
				    </h1>
					<h3 class="now-header-artist">
				        ${artist_link}
				    </h3>
				</div>
			`);
      header_colour(html.node`<img src=${avatar(now2.cover, "avatar300s")} />`, true, [
        now_image
      ]);
    }
  }

